t.script:
document.addEventListener('DOMContentLoaded', function() {
    var canvas = document.getElementById('signatureCanvas');
    if (!canvas) return;
    var ctx = canvas.getContext('2d');
    var isDrawing = false;
    var hasDrawn = false;
    var lastX = 0, lastY = 0;
    var activeTab = 'draw';

    // Resize canvas properly
    function resizeCanvas() {
        var rect = canvas.parentElement.getBoundingClientRect();
        canvas.width = rect.width - 16;
        canvas.height = 200;
        canvas.style.width = (rect.width - 16) + 'px';
        canvas.style.height = '200px';
        ctx.lineWidth = 2.5;
        ctx.lineCap = 'round';
        ctx.lineJoin = 'round';
        ctx.strokeStyle = '#1a1a2e';
    }
    resizeCanvas();
    window.addEventListener('resize', function() { if (!hasDrawn) resizeCanvas(); });

    function getPos(e) {
        var rect = canvas.getBoundingClientRect();
        var touch = e.touches ? e.touches[0] : e;
        return { x: touch.clientX - rect.left, y: touch.clientY - rect.top };
    }
    function startDraw(e) {
        e.preventDefault();
        isDrawing = true;
        var pos = getPos(e);
        lastX = pos.x; lastY = pos.y;
        ctx.beginPath();
        ctx.moveTo(lastX, lastY);
    }
    function draw(e) {
        if (!isDrawing) return;
        e.preventDefault();
        var pos = getPos(e);
        ctx.lineTo(pos.x, pos.y);
        ctx.stroke();
        lastX = pos.x; lastY = pos.y;
        hasDrawn = true;
    }
    function endDraw() { isDrawing = false; }

    canvas.addEventListener('mousedown', startDraw);
    canvas.addEventListener('mousemove', draw);
    canvas.addEventListener('mouseup', endDraw);
    canvas.addEventListener('mouseleave', endDraw);
    canvas.addEventListener('touchstart', startDraw, {passive: false});
    canvas.addEventListener('touchmove', draw, {passive: false});
    canvas.addEventListener('touchend', endDraw);

    // Clear
    var clearBtn = document.getElementById('clearCanvas');
    if (clearBtn) clearBtn.addEventListener('click', function() {
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        hasDrawn = false;
    });

    // Tab switching
    document.querySelectorAll('[data-bs-toggle="tab"]').forEach(function(btn) {
        btn.addEventListener('click', function() {
            var href = this.getAttribute('href') || '';
            if (href.indexOf('draw') >= 0) activeTab = 'draw';
            else if (href.indexOf('type') >= 0) activeTab = 'type';
            else if (href.indexOf('upload') >= 0) activeTab = 'upload';
        });
    });

    // Typed signature
    var typedInput = document.getElementById('typedSignature');

    // Upload signature
    var uploadInput = document.getElementById('uploadSignature');
    var uploadPreview = document.getElementById('uploadPreview');
    if (uploadInput) {
        uploadInput.addEventListener('change', function() {
            var file = this.files[0];
            if (!file) return;
            var reader = new FileReader();
            reader.onload = function(ev) {
                uploadPreview.src = ev.target.result;
                uploadPreview.style.display = 'block';
            };
            reader.readAsDataURL(file);
        });
    }

    // Get signature data
    function getSignatureData() {
        if (activeTab === 'draw') {
            if (!hasDrawn) { alert('Please draw your signature.'); return null; }
            return { signature: canvas.toDataURL('image/png').split(',')[1], signature_type: 'draw' };
        } else if (activeTab === 'type') {
            var text = typedInput ? typedInput.value.trim() : '';
            if (!text) { alert('Please type your name.'); return null; }
            var tc = document.createElement('canvas');
            tc.width = 600; tc.height = 200;
            var tctx = tc.getContext('2d');
            tctx.fillStyle = '#fff'; tctx.fillRect(0,0,600,200);
            tctx.fillStyle = '#1a1a2e';
            tctx.font = 'italic 48px serif';
            tctx.textAlign = 'center'; tctx.textBaseline = 'middle';
            tctx.fillText(text, 300, 100);
            return { signature: tc.toDataURL('image/png').split(',')[1], signature_type: 'type' };
        } else if (activeTab === 'upload') {
            if (!uploadPreview || !uploadPreview.src || uploadPreview.style.display === 'none') {
                alert('Please upload a signature image.'); return null;
            }
            var uc = document.createElement('canvas');
            uc.width = uploadPreview.naturalWidth || 600;
            uc.height = uploadPreview.naturalHeight || 200;
            uc.getContext('2d').drawImage(uploadPreview, 0, 0);
            return { signature: uc.toDataURL('image/png').split(',')[1], signature_type: 'upload' };
        }
        return null;
    }

    // Submit
    var submitBtn = document.getElementById('submitSignature');
    if (submitBtn) {
        submitBtn.addEventListener('click', function() {
            var data = getSignatureData();
            if (!data) return;
            var token = this.getAttribute('data-token');
            submitBtn.disabled = true;
            submitBtn.textContent = 'Submitting...';
            fetch('/sign/' + token + '/submit', {
                method: 'POST',
                headers: {'Content-Type': 'application/json'},
                body: JSON.stringify({jsonrpc: '2.0', method: 'call', params: data}),
            })
            .then(function(r) { return r.json(); })
            .then(function(result) {
                if (result.result && result.result.success) {
                    document.getElementById('signatureSection').style.display = 'none';
                    document.getElementById('successMsg').style.display = 'block';
                } else {
                    var err = (result.result && result.result.error) || 'Unknown error';
                    alert('Error: ' + err);
                    submitBtn.disabled = false;
                    submitBtn.innerHTML = 'Sign Document';
                }
            })
            .catch(function() {
                alert('Network error.');
                submitBtn.disabled = false;
                submitBtn.innerHTML = 'Sign Document';
            });
        });
    }

    // Decline
    var declineBtn = document.getElementById('declineBtn');
    if (declineBtn) {
        declineBtn.addEventListener('click', function() {
            var reason = prompt('Reason for declining (optional):');
            if (reason === null) return;
            var token = submitBtn ? submitBtn.getAttribute('data-token') : '';
            declineBtn.disabled = true;
            fetch('/sign/' + token + '/decline', {
                method: 'POST',
                headers: {'Content-Type': 'application/json'},
                body: JSON.stringify({jsonrpc: '2.0', method: 'call', params: {reason: reason}}),
            })
            .then(function(r) { return r.json(); })
            .then(function(result) {
                if (result.result && result.result.success) {
                    document.getElementById('signatureSection').style.display = 'none';
                    var decMsg = document.createElement('div');
                    decMsg.className = 'alert alert-danger text-center mt-4';
                    decMsg.innerHTML = 'Document Declined. You have declined to sign this document.';
                    document.getElementById('signatureSection').parentNode.appendChild(decMsg);
                } else { alert('Error'); declineBtn.disabled = false; }
            })
            .catch(function() { alert('Network error.'); declineBtn.disabled = false; });
        });
    }
});
